#include <zephyr/drivers/sensor.h>
#include <zephyr/drivers/spi.h>
#include <zephyr/drivers/spi_emul.h>
#include <zephyr/kernel.h>
#include <zephyr/logging/log.h>
#include "bmi160.h"

LOG_MODULE_REGISTER(bmi160_emul, CONFIG_SENSOR_LOG_LEVEL);

#define BMI160_REG_MAX_ADDR 0x80

struct bmi160_emul_data {
	struct spi_emul_data emul_data;
	uint8_t regs[BMI160_REG_MAX_ADDR];
};

static int bmi160_emul_read_reg(const struct device *dev, uint8_t reg_addr, uint8_t *val)
{
	struct bmi160_emul_data *data = dev->data;

	if (reg_addr >= BMI160_REG_MAX_ADDR) {
		LOG_ERR("Invalid register address 0x%02x for read", reg_addr);
		return -EINVAL;
	}

	*val = data->regs[reg_addr];
	return 0;
}

static int bmi160_emul_write_reg(const struct device *dev, uint8_t reg_addr, uint8_t val)
{
	struct bmi160_emul_data *data = dev->data;

	if (reg_addr >= BMI160_REG_MAX_ADDR) {
		LOG_ERR("Invalid register address 0x%02x for write", reg_addr);
		return -EINVAL;
	}

	data->regs[reg_addr] = val;
	return 0;
}

static int bmi160_emul_get_reg_value_range(const struct device *dev, uint8_t reg_addr,
					    uint8_t *val, uint8_t mask, uint8_t shift)
{
	int ret;
	uint8_t reg_val;

	ret = bmi160_emul_read_reg(dev, reg_addr, &reg_val);
	if (ret < 0) {
		return ret;
	}

	*val = (reg_val & mask) >> shift;
	return 0;
}

static int bmi160_emul_set_reg_value_range(const struct device *dev, uint8_t reg_addr,
					    uint8_t val, uint8_t mask, uint8_t shift)
{
	int ret;
	uint8_t reg_val;

	ret = bmi160_emul_read_reg(dev, reg_addr, &reg_val);
	if (ret < 0) {
		return ret;
	}

	reg_val = (reg_val & ~mask) | ((val << shift) & mask);

	return bmi160_emul_write_reg(dev, reg_addr, reg_val);
}

static int bmi160_emul_transfer_spi(const struct spi_emul *emul, struct spi_message *msg,
				    bool write)
{
	struct bmi160_emul_data *data = emul->data;
	struct spi_buf *tx_buf = &msg->spi_bufs[0].buf;
	struct spi_buf *rx_buf = &msg->spi_bufs[0].buf;
	uint8_t reg_addr;
	int ret = 0;

	if (tx_buf->len < 1) {
		return -EINVAL;
	}

	reg_addr = ((uint8_t *)tx_buf->buf)[0];

	if (write) {
		/* Write operation: first byte is address, subsequent bytes are data */
		if (tx_buf->len < 2) {
			return -EINVAL;
		}
		for (size_t i = 1; i < tx_buf->len; i++) {
			ret = bmi160_emul_write_reg(emul->dev, reg_addr + i - 1,
						((uint8_t *)tx_buf->buf)[i]);
			if (ret < 0) {
				return ret;
			}
		}
	} else {
		/* Read operation: first byte is address (MSB set), subsequent bytes are data */
		reg_addr &= ~BIT(7); /* Clear R/W bit */

		if (rx_buf->len < 2) {
			return -EINVAL;
		}

		/* First byte is dummy read, actual data starts from second byte */
		for (size_t i = 1; i < rx_buf->len; i++) {
			ret = bmi160_emul_read_reg(emul->dev, reg_addr + i - 1,
						&((uint8_t *)rx_buf->buf)[i]);
			if (ret < 0) {
				return ret;
			}
		}
	}

	return ret;
}

static int bmi160_emul_init(const struct device *dev)
{
	struct bmi160_emul_data *data = dev->data;

	/* Initialize all registers to 0, then set known default values */
	(void)memset(data->regs, 0, sizeof(data->regs));

	data->regs[BMI160_CHIP_ID_ADDR] = BMI160_CHIP_ID;

	spi_emul_init(&data->emul_data, dev, bmi160_emul_transfer_spi);

	return 0;
}

const struct bmi160_emul_api {
	int (*read_reg)(const struct device *dev, uint8_t reg_addr, uint8_t *val);
	int (*write_reg)(const struct device *dev, uint8_t reg_addr, uint8_t val);
	int (*get_reg_value_range)(const struct device *dev, uint8_t reg_addr,
				   uint8_t *val, uint8_t mask, uint8_t shift);
	int (*set_reg_value_range)(const struct device *dev, uint8_t reg_addr,
				   uint8_t val, uint8_t mask, uint8_t shift);
} bmi160_emul_api_funcs = {
	.read_reg = bmi160_emul_read_reg,
	.write_reg = bmi160_emul_write_reg,
	.get_reg_value_range = bmi160_emul_get_reg_value_range,
	.set_reg_value_range = bmi160_emul_set_reg_value_range,
};

#define BMI160_EMUL_DEFINE(n) \
	static struct bmi160_emul_data bmi160_emul_data_##n; \
	DEVICE_DT_DEFINE(DT_NODELABEL(bmi160_emul_##n), \
			 bmi160_emul_init, NULL, \
			 &bmi160_emul_data_##n, NULL, POST_KERNEL, \
			 CONFIG_SENSOR_INIT_PRIORITY, \
			 &bmi160_emul_api_funcs);

DT_FOREACH_STATUS_OKAY(bosch_bmi160_emul, BMI160_EMUL_DEFINE)
